INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Global Catastrophic Wildfire Prevention Day 2026', 'Bay Area Health Tech Innovators', 'Founders & Startups', 'The second Global Catastrophic Wildfire Prevention Day, aligned with the UN International Day of Disaster Risk Reduction. Convened by the', 'The second Global Catastrophic Wildfire Prevention Day, aligned with the UN International Day of Disaster Risk Reduction. Convened by the Catastrophic Wildfire Prevention Consortium (CWPC) at CrowdDoing and ARISE-US (affiliated with UNDRR), with the Wildfire Innovation Showcase 1:00-3:30 PM in partnership with Venture Starters. Free. Program and registration: https://luma.com/xex7pq73 More info: https://www.meetup.com/bay-area-health-tech-innovators/events/316862017/', '2026-10-13T09:00:00-07:00', 'Online event', 'Online event', 'San Francisco', 'CA', '', 37.78, -122.42, 'Bay Area Health Tech Innovators', 0, true, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-health-tech-innovators/events/316862017/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Breakfast with Stephen Gomes — Kinship Earth', 'Bay Area Health Tech Innovators', 'Founders & Startups', 'A relaxed, conversational pre-festival breakfast with Stephen Gomes — co-founder of Kinship Earth and Gaia''s Inc., former Bechtel Global', 'A relaxed, conversational pre-festival breakfast with Stephen Gomes — co-founder of Kinship Earth and Gaia''s Inc., former Bechtel Global Project Manager. Meet builders, organizers, funders, and regeneration-minded people over coffee and breakfast (available for purchase). Details: https://luma.com/ohzvlgk8 More info: https://www.meetup.com/bay-area-health-tech-innovators/events/316862031/', '2026-10-17T08:00:00-07:00', 'Mabuhay Gardens', '443 Broadway, San Francisco, CA 94133, USA', 'San Francisco', 'CA', '94133', 37.798074600291, -122.404566144684, 'Bay Area Health Tech Innovators', 0, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-health-tech-innovators/events/316862031/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('Shared Origins, Bright Mutual Future', 'Bay Area Health Tech Innovators', 'Founders & Startups', 'An ancient-future solarpunk gathering in the San Francisco Bay bioregion. Co-convened by CrowdDoing and Solarpunkification, hosted at', 'An ancient-future solarpunk gathering in the San Francisco Bay bioregion. Co-convened by CrowdDoing and Solarpunkification, hosted at Mabuhay Gardens, supported by Kinship Earth — a registered public satellite event of the ORIGIN Global Festival (Cradle of Humankind, South Africa). Talks, a Warm Data Lab, festival tables, live uplinks to the ORIGIN global broadcast, and food for sale from 8:30 AM. Free or by suggested donation. Tickets: https://luma.com/90i6vrae More info: https://www.meetup.com/bay-area-health-tech-innovators/events/316862046/', '2026-10-17T08:00:00-07:00', 'Mabuhay Gardens', '443 Broadway, San Francisco, CA 94133, USA', 'San Francisco', 'CA', '94133', 37.798074600291, -122.404566144684, 'Bay Area Health Tech Innovators', 0, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-health-tech-innovators/events/316862046/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('A Warm Data Lab at Shared Origins, Bright Mutual Future', 'Bay Area Health Tech Innovators', 'Founders & Startups', 'A facilitated Warm Data Lab as part of the day''s festival — share stories around a common question, move between small groups to explore it', 'A facilitated Warm Data Lab as part of the day''s festival — share stories around a common question, move between small groups to explore it from different viewpoints, and gather to share insights. Co-hosted with Jess Groopman. Everyone welcome; no preparation needed. Registration: https://luma.com/g9l0pkv0 More info: https://www.meetup.com/bay-area-health-tech-innovators/events/316862056/', '2026-10-17T09:50:00-07:00', 'Mabuhay Gardens', '443 Broadway, San Francisco, CA 94133, USA', 'San Francisco', 'CA', '94133', 37.798074600291, -122.404566144684, 'Bay Area Health Tech Innovators', 0, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/bay-area-health-tech-innovators/events/316862056/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
